using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using pet_project.Data; using pet_project.Models; namespace pet_project.Controllers;
public class SheltersController:Controller { readonly AppDbContext c; public SheltersController(AppDbContext c)=>this.c=c; public async Task<IActionResult>Index()=>View(await c.Shelters.ToListAsync()); public async Task<IActionResult>Details(int? id){if(id==null)return NotFound();var x=await c.Shelters.Include(x=>x.Pets).FirstOrDefaultAsync(x=>x.Id==id);return x==null?NotFound():View(x);} public IActionResult Create()=>View(); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult>Create([Bind("Id,Name,City,Phone")]Shelter x){if(!ModelState.IsValid)return View(x);c.Add(x);await c.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult>Edit(int? id){if(id==null)return NotFound();var x=await c.Shelters.FindAsync(id);return x==null?NotFound():View(x);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult>Edit(int id,[Bind("Id,Name,City,Phone")]Shelter x){if(id!=x.Id)return NotFound();if(!ModelState.IsValid)return View(x);c.Update(x);await c.SaveChangesAsync();return RedirectToAction(nameof(Index));} public async Task<IActionResult>Delete(int? id){if(id==null)return NotFound();var x=await c.Shelters.FirstOrDefaultAsync(x=>x.Id==id);return x==null?NotFound():View(x);} [HttpPost,ActionName("Delete"),ValidateAntiForgeryToken] public async Task<IActionResult>DeleteConfirmed(int id){var x=await c.Shelters.FindAsync(id);if(x!=null)c.Shelters.Remove(x);await c.SaveChangesAsync();return RedirectToAction(nameof(Index));} }
